package com.lagalarm;

import java.io.FileDescriptor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.client.plugins.worldhopper.ping.TCPInfo;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import static com.lagalarm.LagAlarmPlugin.now;

/** Borrows the game socket to read OS TCP statistics. Does not send probes or read game packets. */
final class GameSocketMonitor
{
    static final int POLL_INTERVAL_MS = 250;

    private static final Logger log = LoggerFactory.getLogger(GameSocketMonitor.class);
    private static final int MAX_FAILURES = 6;
    private static final int MAX_RETRY_DELAY_MS = 30000;

    private final Client client;
    private final LagDetector detector;
    private volatile boolean active = true;
    private volatile CapturedSocket socket;

    // Client-thread state.
    private long nextCaptureAt;
    private int captureFailures;

    // Worker state. Fixed-delay scheduling prevents overlapping polls.
    private CapturedSocket previous;
    private long retryAt;
    private int queryFailures;

    GameSocketMonitor(Client client, LagDetector detector)
    {
        this.client = client;
        this.detector = detector;
    }

    // Called on the client thread; the worker never calls Client.getSocketFD().
    void captureSocket(long time)
    {
        if (!active || time < nextCaptureAt)
        {
            return;
        }
        nextCaptureAt = time + POLL_INTERVAL_MS;
        if (client.getGameState() != GameState.LOGGED_IN)
        {
            socket = null;
            return;
        }
        try
        {
            FileDescriptor gameSocket = client.getSocketFD();
            LagDetector.ConnectionToken connection = detector.trackSocketIdentity(gameSocket);
            socket = gameSocket == null || connection == null ? null : new CapturedSocket(gameSocket, connection);
            captureFailures = 0;
        }
        catch (RuntimeException | LinkageError ex)
        {
            CapturedSocket captured = socket;
            socket = null;
            if (captured != null)
            {
                detector.markTcpUnavailable(captured.connection, captured.gameSocket);
            }
            captureFailures = Math.min(MAX_FAILURES, captureFailures + 1);
            nextCaptureAt = time + retryDelay(captureFailures);
            log.debug("Game socket unavailable; tick and ICMP checks remain active", ex);
        }
    }

    // Called on the client thread before updating the detector's connection state.
    void onGameStateChanged(GameState state)
    {
        if (state != GameState.LOGGED_IN)
        {
            socket = null;
        }
        nextCaptureAt = 0;
    }

    // Called by the scheduled worker; native queries stay off the client thread.
    void pollSocketStatistics()
    {
        if (!active)
        {
            return;
        }
        CapturedSocket captured = socket;
        if (captured == null)
        {
            return;
        }
        if (previous == null || previous.gameSocket != captured.gameSocket
            || previous.connection.generation != captured.connection.generation)
        {
            previous = captured;
            queryFailures = 0;
            retryAt = 0;
        }
        if (now() < retryAt)
        {
            return;
        }
        try
        {
            // Same helper as World Hopper. This queries existing OS counters without sending packets.
            TCPInfo info = Ping.getTCPInfo(captured.gameSocket);
            if (info != null && info.getRTT() > 0 && info.getTransmitted() >= 0 && info.getRetransmitted() >= 0)
            {
                // Native RTT is microseconds. Preserve valid sub-millisecond measurements.
                int rtt = (int) Math.min(Integer.MAX_VALUE, (info.getRTT() + 999) / 1000);
                if (active)
                {
                    // The detector rejects results from an old world, generation or socket.
                    detector.recordTcpSample(captured.connection, captured.gameSocket,
                        rtt, info.getTransmitted(), info.getRetransmitted(), now());
                }
                queryFailures = 0;
                return;
            }
        }
        catch (RuntimeException | LinkageError ex)
        {
            log.debug("Game socket statistics unavailable; tick and ICMP checks remain active", ex);
        }
        if (active)
        {
            detector.markTcpUnavailable(captured.connection, captured.gameSocket);
        }
        queryFailures = Math.min(MAX_FAILURES, queryFailures + 1);
        retryAt = now() + retryDelay(queryFailures);
    }

    void stop()
    {
        // Each plugin start creates a new monitor; an old worker can never become active again.
        active = false;
        socket = null;
    }

    private static long retryDelay(int failures)
    {
        return Math.min(MAX_RETRY_DELAY_MS, 1000L << (failures - 1));
    }

    // The handle is borrowed. RuneLite owns the socket's lifetime; this plugin never closes it.
    private static final class CapturedSocket
    {
        final FileDescriptor gameSocket;
        final LagDetector.ConnectionToken connection;

        CapturedSocket(FileDescriptor gameSocket, LagDetector.ConnectionToken connection)
        {
            this.gameSocket = gameSocket;
            this.connection = connection;
        }
    }
}

package com.lagalarm;

import net.runelite.client.game.WorldService;
import net.runelite.client.plugins.worldhopper.ping.Ping;
import net.runelite.http.api.worlds.World;
import net.runelite.http.api.worlds.WorldResult;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

import static com.lagalarm.LagAlarmPlugin.now;

/** Active probes of the current world. Separate from passive game-socket statistics. */
final class IcmpMonitor
{
    static final int SCHEDULE_CHECK_INTERVAL_MS = 25;

    private static final Logger log = LoggerFactory.getLogger(IcmpMonitor.class);

    private final WorldService worldService;
    private final LagDetector detector;
    private final IcmpProbePacer pacer = new IcmpProbePacer();
    private volatile boolean active = true;

    IcmpMonitor(WorldService worldService, LagDetector detector)
    {
        this.worldService = worldService;
        this.detector = detector;
    }

    // Called by one scheduled worker. The pacer determines the actual probe interval.
    void probeCurrentWorld()
    {
        LagDetector.ConnectionToken connection = null;
        boolean started = false;
        try
        {
            if (!active)
            {
                return;
            }
            connection = detector.currentConnection();
            if (connection == null || !pacer.ready(connection, now()))
            {
                return;
            }
            WorldResult worlds = worldService.getWorlds();
            World world = worlds == null ? null : worlds.findWorld(connection.world);
            if (!active || world == null || !detector.beginIcmpProbe(connection, now()))
            {
                return;
            }
            started = true;
            // Reuse RuneLite's helper without requiring World Hopper to be enabled.
            // On Windows/macOS/Linux, false disables the TCP-connect fallback.
            // Failed ICMP is an unknown measurement, not proof of game-connection loss.
            int result = Ping.ping(world, false);
            if (active)
            {
                detector.recordIcmpSample(connection, result, now());
            }
        }
        catch (RuntimeException | LinkageError ex)
        {
            if (started && active)
            {
                detector.recordIcmpSample(connection, -1, now());
            }
            log.debug("Ping unavailable; passive tick monitoring remains active", ex);
        }
        finally
        {
            if (started && active)
            {
                pacer.finished(connection, now(), detector.icmpProbeDelay());
            }
        }
    }

    void stop()
    {
        // A stopped instance is never reused, including its pacing state.
        active = false;
    }
}

package com.lagalarm;

import java.util.concurrent.ThreadLocalRandom;

/** Completion-based pacing shared by the plugin and live benchmark. */
final class IcmpProbePacer
{
    private boolean scheduled;
    private long generation;
    private long nextProbeAt;

    synchronized boolean ready(LagDetector.ConnectionToken connection, long now)
    {
        return !scheduled || connection.generation != generation || now >= nextProbeAt;
    }

    synchronized void finished(LagDetector.ConnectionToken connection, long now, int delayMs)
    {
        int variation = Math.max(1, delayMs / 10);
        nextProbeAt = now + delayMs + ThreadLocalRandom.current().nextInt(-variation, variation + 1);
        generation = connection.generation;
        scheduled = true;
    }
}

package com.lagalarm;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(LagAlarmConfig.GROUP)
public interface LagAlarmConfig extends Config
{
    String GROUP = "lag-alarm";

    @ConfigItem(keyName = "soundEnabled", name = "Spoken lag alert", position = 0,
        description = "Say 'lag' during an alarm, repeating every four seconds. Unconfirmed ping cautions remain silent. Works independently of the visual alert.")
    default boolean soundEnabled()
    {
        return true;
    }

    @ConfigItem(keyName = "visualAlert", name = "Visual alert", position = 1,
        description = "Show a click-through warning in the chatbox area, even with chat hidden: banner with pulsing border, banner alone, or off. Sound is controlled separately. Shift+F10 previews the alerts.")
    default VisualAlert visualAlert()
    {
        return VisualAlert.BANNER_AND_BORDER;
    }
}

package com.lagalarm;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

public class LagAlarmOverlay extends Overlay
{
    private final Client client;
    private final LagAlarmPlugin plugin;
    private final LagAlarmConfig config;

    @Inject
    LagAlarmOverlay(Client client, LagAlarmPlugin plugin, LagAlarmConfig config)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
        setPriority(PRIORITY_HIGH);
        setMovable(false);
        setSnappable(false);
        setDragTargetable(false);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        LagDetector.Snapshot snapshot = plugin.getSnapshot();
        if (snapshot.mode == LagDetector.Mode.IDLE || !snapshot.hasWarning())
        {
            return null;
        }
        VisualAlert visual = config.visualAlert();
        if (visual == VisualAlert.OFF)
        {
            return null;
        }
        Color color = new Color(255, 176, 64);
        LagAlarmPainter.paint(graphics, client.getCanvasWidth(), client.getCanvasHeight(), chatboxBounds(),
            snapshot, color, visual == VisualAlert.BANNER_AND_BORDER && snapshot.isAlarm(), LagAlarmPlugin.now());
        return null;
    }

    private Rectangle chatboxBounds()
    {
        Widget chatbox = client.getWidget(InterfaceID.Chatbox.UNIVERSE);
        Widget controls = client.getWidget(InterfaceID.Chatbox.CONTROLS);
        // Hiding chat does not hide our independent overlay or invalidate its layout bounds.
        return LagAlarmPainter.chatboxArea(client.getCanvasWidth(), client.getCanvasHeight(),
            chatbox == null ? null : chatbox.getBounds(), controls == null ? null : controls.getBounds());
    }
}

package com.lagalarm;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Locale;

/** Rendering only; shared by the actual overlay and the headless preview. */
final class LagAlarmPainter
{
    private static final Font TITLE = new Font(Font.SANS_SERIF, Font.BOLD, 24);
    private static final Font BODY = new Font(Font.SANS_SERIF, Font.PLAIN, 13);
    private static final Font SMALL = new Font(Font.SANS_SERIF, Font.PLAIN, 12);
    private static final Color PANEL = new Color(20, 24, 31, 242);
    private static final Color TEXT = new Color(236, 239, 243);

    static void paint(Graphics2D original, int width, int height, Rectangle chatbox, LagDetector.Snapshot snapshot,
        Color color, boolean pulse, long now)
    {
        if (width < 140 || height < 140 || snapshot.mode == LagDetector.Mode.IDLE || !snapshot.hasWarning())
        {
            return;
        }
        Rectangle bounds = warningBounds(width, height, chatbox);
        if (bounds == null)
        {
            return;
        }
        int x = bounds.x;
        int y = bounds.y;
        int w = bounds.width;
        Graphics2D g = (Graphics2D) original.create();
        try
        {
            // Keep all visual effects within the chat area, even when chat itself is hidden.
            g.clip(chatbox.intersection(new Rectangle(0, 0, width, height)));
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (pulse)
            {
                // Keep the pulse local to the warning; do not frame the entire game canvas.
                int alpha = (int) (100 + 80 * (0.5 + 0.5 * Math.sin(now * Math.PI / 750.0)));
                g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), alpha));
                g.setStroke(new BasicStroke(4));
                g.drawRoundRect(x - 3, y - 3, w + 6, bounds.height + 6, 18, 18);
            }
            g.setColor(new Color(0, 0, 0, 90));
            g.fillRoundRect(x + 3, y + 4, w, bounds.height, 14, 14);
            g.setColor(PANEL);
            g.fillRoundRect(x, y, w, bounds.height, 14, 14);
            g.setColor(color);
            g.setStroke(new BasicStroke(2));
            g.drawRoundRect(x, y, w, bounds.height, 14, 14);
            String title = snapshot.confidence == LagDetector.Confidence.CAUTION ? "PING WARNING"
                : snapshot.reason == LagDetector.Reason.TEST ? "LAG ALARM - TEST"
                : snapshot.reason == LagDetector.Reason.CLIENT_STALL ? "CLIENT DELAY DETECTED"
                : snapshot.reason == LagDetector.Reason.PROBE_DELAY || snapshot.reason == LagDetector.Reason.PROBE_FAILURES
                ? "CONNECTION WARNING" : "LAG DETECTED";
            g.setFont(TITLE);
            if (bounds.height < 90)
            {
                // A collapsed chatbox only has room for a single-line warning.
                g.setFont(TITLE.deriveFont((float) Math.min(20, bounds.height - 4)));
                FontMetrics metrics = g.getFontMetrics();
                centered(g, title, x, y + (bounds.height - metrics.getHeight()) / 2 + metrics.getAscent(), w);
                return;
            }
            centered(g, title, x, y + 33, w);
            g.setFont(BODY);
            g.setColor(TEXT);
            centered(g, detail(snapshot), x, y + 58, w);
            g.setFont(SMALL);
            g.setColor(new Color(172, 182, 196));
            String footer = snapshot.reason == LagDetector.Reason.TEST
                ? "Preview only - connection unchanged"
                : snapshot.confidence == LagDetector.Confidence.CAUTION ? "Game connection trouble is not confirmed"
                : "WORLD " + snapshot.world + "  |  Waiting for stable connection and updates";
            centered(g, footer, x, y + 81, w);
        }
        finally
        {
            g.dispose();
        }
    }

    static Rectangle warningBounds(int width, int height, Rectangle chatbox)
    {
        Rectangle visibleChat = chatbox == null ? null : chatbox.intersection(new Rectangle(0, 0, width, height));
        if (visibleChat == null || visibleChat.width < 140 || visibleChat.height < 20)
        {
            return null;
        }
        int verticalMargin = visibleChat.height >= 116 ? 8 : 2;
        int w = Math.min(510, visibleChat.width - 16);
        int h = Math.min(100, visibleChat.height - 2 * verticalMargin);
        int x = visibleChat.x + (visibleChat.width - w) / 2;
        int y = visibleChat.y + (visibleChat.height - h) / 2;
        return new Rectangle(x, y, w, h);
    }

    static Rectangle chatboxArea(int width, int height, Rectangle chatbox, Rectangle controls)
    {
        Rectangle canvas = new Rectangle(0, 0, width, height);
        for (Rectangle candidate : new Rectangle[] {chatbox, controls})
        {
            if (candidate == null)
            {
                continue;
            }
            Rectangle area = candidate.intersection(canvas);
            if (area.width < 140 || area.height < 20)
            {
                continue;
            }
            if (area.height < 100)
            {
                // Collapsed chat retains its bottom controls; restore the usual footprint above them.
                int bottom = area.y + area.height;
                area.height = Math.min(165, bottom);
                area.y = bottom - area.height;
            }
            return area;
        }
        // Also works when the plugin starts with chat already hidden and no usable widget bounds.
        int chatHeight = Math.min(165, height);
        return new Rectangle(0, height - chatHeight, Math.min(519, width), chatHeight);
    }

    private static String detail(LagDetector.Snapshot snapshot)
    {
        switch (snapshot.reason)
        {
            case CLIENT_STALL:
                return "Local client updates have also paused";
            case HIGH_PING:
                return "Sustained high ping - latest " + snapshot.pingMs + " ms";
            case TCP_LATENCY:
                return "Game connection latency is high - latest " + snapshot.tcpRttMs + " ms";
            case TCP_RETRANSMISSIONS:
                return "Game connection is repeatedly retransmitting data";
            case PROBE_DELAY:
                return "Ping reply delayed - connection may be unstable";
            case PROBE_FAILURES:
                return "Recent ping probes failed - check connection stability";
            case RECOVERING:
                return "Updates resumed - confirming recovery";
            case TEST:
                return "Previewing your selected lag alerts";
            default:
                return String.format(Locale.ROOT, "No game update for %.1f seconds", snapshot.tickAgeMs / 1000.0);
        }
    }

    private static void centered(Graphics2D g, String text, int x, int y, int width)
    {
        FontMetrics metrics = g.getFontMetrics();
        if (metrics.stringWidth(text) > width - 24)
        {
            float size = g.getFont().getSize2D() * (width - 24) / metrics.stringWidth(text);
            g.setFont(g.getFont().deriveFont(size));
            metrics = g.getFontMetrics();
        }
        g.drawString(text, x + (width - metrics.stringWidth(text)) / 2, y);
    }
}

package com.lagalarm;

import com.google.inject.Provides;
import java.awt.event.InputEvent;
import java.awt.event.KeyEvent;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.client.audio.AudioPlayer;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.Keybind;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.WorldService;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(name = "Lag Alarm", internalName = "lag-alarm",
    description = "Distinct visual and audio warnings for delayed game updates and sustained high ping",
    tags = {"lag", "latency", "hardcore", "ironman", "alarm", "ping"})
public class LagAlarmPlugin extends Plugin
{
    private static final Logger log = LoggerFactory.getLogger(LagAlarmPlugin.class);
    private static final int WATCHDOG_INTERVAL_MS = 25;

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private LagAlarmConfig config;

    @Inject
    private ConfigManager configManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private LagAlarmOverlay overlay;

    @Inject
    private WorldService worldService;

    @Inject
    private AudioPlayer audioPlayer;

    @Inject
    private KeyManager keyManager;

    private final LagDetector detector = new LagDetector();
    private volatile LagDetector.Snapshot snapshot = detector.evaluate(0);
    private volatile boolean running;
    private volatile long runGeneration;
    private volatile SoundSettings soundSettings = new SoundSettings(true, 60, 4);
    private ScheduledExecutorService workers;
    private GameSocketMonitor socketMonitor;
    private IcmpMonitor icmpMonitor;
    private final AtomicBoolean soundPending = new AtomicBoolean();
    private long lastSound;
    private boolean previouslyAlarmed;

    private final HotkeyListener testKey = new HotkeyListener(() -> new Keybind(KeyEvent.VK_F10, InputEvent.SHIFT_DOWN_MASK))
    {
        @Override
        public void hotkeyPressed()
        {
            if (running)
            {
                detector.test(now());
            }
        }
    };

    @Provides
    LagAlarmConfig provideConfig(ConfigManager manager)
    {
        return manager.getConfig(LagAlarmConfig.class);
    }

    @Override
    protected void startUp()
    {
        detector.stop();
        migrateAlertPreference();
        refreshSettings();
        previouslyAlarmed = false;
        soundPending.set(false);
        long generation = ++runGeneration;
        // Scheduled tasks retain these instances, so an old run cannot poll a replacement monitor.
        GameSocketMonitor sockets = new GameSocketMonitor(client, detector);
        IcmpMonitor icmp = new IcmpMonitor(worldService, detector);
        socketMonitor = sockets;
        icmpMonitor = icmp;
        running = true;
        // Keep native socket queries, ICMP and audio off both the client thread and the watchdog.
        ScheduledExecutorService executor = Executors.newScheduledThreadPool(4, runnable ->
        {
            Thread thread = new Thread(runnable, "lag-alarm-worker");
            thread.setDaemon(true);
            return thread;
        });
        workers = executor;
        overlayManager.add(overlay);
        keyManager.registerKeyListener(testKey);
        clientThread.invokeLater(() ->
        {
            if (isCurrent(generation))
            {
                updateState(client.getGameState());
            }
        });
        executor.scheduleWithFixedDelay(() -> checkForLag(generation, executor),
            0, WATCHDOG_INTERVAL_MS, TimeUnit.MILLISECONDS);
        // Fixed delay avoids backlogs or overlapping probes when ICMP times out.
        executor.scheduleWithFixedDelay(icmp::probeCurrentWorld, IcmpMonitor.SCHEDULE_CHECK_INTERVAL_MS,
            IcmpMonitor.SCHEDULE_CHECK_INTERVAL_MS, TimeUnit.MILLISECONDS);
        executor.scheduleWithFixedDelay(sockets::pollSocketStatistics, GameSocketMonitor.POLL_INTERVAL_MS,
            GameSocketMonitor.POLL_INTERVAL_MS, TimeUnit.MILLISECONDS);
    }

    @Override
    protected void shutDown()
    {
        running = false;
        runGeneration++;
        if (socketMonitor != null)
        {
            socketMonitor.stop();
            socketMonitor = null;
        }
        if (icmpMonitor != null)
        {
            icmpMonitor.stop();
            icmpMonitor = null;
        }
        // This executor belongs only to this plugin run; stop all scheduled tasks together.
        if (workers != null)
        {
            workers.shutdownNow();
            workers = null;
        }
        keyManager.unregisterKeyListener(testKey);
        overlayManager.remove(overlay);
        detector.stop();
        snapshot = detector.evaluate(now());
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (running && client.getGameState() == GameState.LOGGED_IN)
        {
            detector.loggedIn(client.getWorld(), now());
            detector.tick(now());
        }
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        GameSocketMonitor sockets = socketMonitor;
        if (!running || sockets == null)
        {
            return;
        }
        long time = now();
        detector.clientTick(time);
        sockets.captureSocket(time);
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (running)
        {
            updateState(event.getGameState());
        }
    }

    private void updateState(GameState state)
    {
        GameSocketMonitor sockets = socketMonitor;
        if (!running || sockets == null)
        {
            return;
        }
        sockets.onGameStateChanged(state);
        switch (state)
        {
            case LOGGED_IN:
                detector.loggedIn(client.getWorld(), now());
                break;
            case LOADING:
                detector.loading(now());
                break;
            case CONNECTION_LOST:
                detector.connectionLost();
                break;
            // Includes intentional hops, logout, and fresh login attempts.
            default:
                detector.stop();
                break;
        }
        snapshot = detector.evaluate(now());
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (LagAlarmConfig.GROUP.equals(event.getGroup()))
        {
            refreshSettings();
        }
    }

    private void refreshSettings()
    {
        detector.configure(LagDetector.Settings.automatic());
        soundSettings = new SoundSettings(config.soundEnabled(), 60, 4);
    }

    private void migrateAlertPreference()
    {
        // Preserve the earlier preference for a steady banner when introducing the visual-mode selector.
        if (configManager.getConfiguration(LagAlarmConfig.GROUP, "visualAlert") == null
            && "false".equals(configManager.getConfiguration(LagAlarmConfig.GROUP, "pulseBorder")))
        {
            configManager.setConfiguration(LagAlarmConfig.GROUP, "visualAlert", VisualAlert.BANNER);
        }
    }

    private void checkForLag(long generation, ScheduledExecutorService executor)
    {
        try
        {
            if (!isCurrent(generation))
            {
                return;
            }
            long time = now();
            LagDetector.Snapshot next = detector.evaluate(time);
            if (!isCurrent(generation))
            {
                return;
            }
            snapshot = next;
            SoundSettings sound = soundSettings;
            if (next.isAlarm() && sound.enabled
                && (!previouslyAlarmed || time - lastSound >= sound.repeatMs)
                && soundPending.compareAndSet(false, true))
            {
                lastSound = time;
                executor.execute(() ->
                {
                    try
                    {
                        if (isCurrent(generation) && detector.evaluate(now()).isAlarm() && soundSettings.enabled)
                        {
                            audioPlayer.play(LagAlarmPlugin.class, "lag-voice.wav", sound.gain);
                        }
                    }
                    catch (Exception ex)
                    {
                        log.debug("Unable to play spoken lag alert", ex);
                    }
                    finally
                    {
                        soundPending.set(false);
                    }
                });
            }
            previouslyAlarmed = next.isAlarm();
        }
        catch (RuntimeException ex)
        {
            // A thrown exception must not silently cancel all future scheduled checks.
            log.debug("Lag watchdog check failed", ex);
        }
    }

    private boolean isCurrent(long generation)
    {
        return running && generation == runGeneration;
    }

    LagDetector.Snapshot getSnapshot()
    {
        return snapshot;
    }

    static long now()
    {
        return TimeUnit.NANOSECONDS.toMillis(System.nanoTime());
    }

    private static final class SoundSettings
    {
        final boolean enabled;
        final float gain;
        final long repeatMs;

        SoundSettings(boolean enabled, int volume, int repeatSeconds)
        {
            this.enabled = enabled;
            gain = (float) (20 * Math.log10(Math.max(1, Math.min(100, volume)) / 100.0));
            repeatMs = Math.max(1, Math.min(30, repeatSeconds)) * 1000L;
        }
    }
}

package com.lagalarm;

/** Thread-safe, constant-space detector. All times are monotonic milliseconds. No RuneLite or I/O dependency. */
final class LagDetector
{
    private static final int GAME_TICK_LATE_MS = 900;
    private static final int CLIENT_TICK_STALE_MS = 500;
    private static final int MIN_HEALTHY_TICK_INTERVAL_MS = 300;
    private static final int MAX_HEALTHY_TICK_INTERVAL_MS = 1000;
    private static final int ICMP_SAMPLE_MAX_AGE_MS = 5000;
    private static final int ICMP_COMPLETION_MAX_AGE_MS = 10000;
    private static final int ICMP_HISTORY_MAX_AGE_MS = 30000;
    private static final int TEST_ALERT_DURATION_MS = 5000;

    enum Mode
    {
        IDLE,
        MONITORING,
        LOADING
    }

    enum Reason
    {
        NONE,
        TICK_STALL,
        CLIENT_STALL,
        HIGH_PING,
        TCP_LATENCY,
        TCP_RETRANSMISSIONS,
        PROBE_DELAY,
        PROBE_FAILURES,
        RECOVERING,
        TEST
    }

    enum Confidence
    {
        NONE,
        CAUTION,
        ALARM
    }

    static final class Settings
    {
        final int stallMs;
        final int loginGraceMs;
        final int loadingGraceMs;
        final boolean pingEnabled;
        final int pingThresholdMs;
        final int highPingSamples;
        final boolean earlyWarning;
        final int probeDeadlineMs;
        final int failurePercent;
        final int failureWindow;
        final boolean adaptive;

        Settings(int stallMs, int loginGraceMs, int loadingGraceMs, boolean pingEnabled, int pingThresholdMs)
        {
            this(stallMs, loginGraceMs, loadingGraceMs, pingEnabled, pingThresholdMs, 2, false, 600, 20, 20);
        }

        Settings(int stallMs, int loginGraceMs, int loadingGraceMs, boolean pingEnabled, int pingThresholdMs,
            int highPingSamples, boolean earlyWarning, int probeDeadlineMs, int failurePercent, int failureWindow)
        {
            this(stallMs, loginGraceMs, loadingGraceMs, pingEnabled, pingThresholdMs, highPingSamples,
                earlyWarning, probeDeadlineMs, failurePercent, failureWindow, false);
        }

        private Settings(int stallMs, int loginGraceMs, int loadingGraceMs, boolean pingEnabled, int pingThresholdMs,
            int highPingSamples, boolean earlyWarning, int probeDeadlineMs, int failurePercent, int failureWindow, boolean adaptive)
        {
            this.adaptive = adaptive;
            this.stallMs = Math.max(900, Math.min(10000, stallMs));
            this.loginGraceMs = Math.max(0, Math.min(15000, loginGraceMs));
            this.loadingGraceMs = Math.max(0, Math.min(10000, loadingGraceMs));
            this.pingEnabled = pingEnabled;
            this.pingThresholdMs = Math.max(100, Math.min(2000, pingThresholdMs));
            this.highPingSamples = Math.max(1, Math.min(10, highPingSamples));
            this.earlyWarning = earlyWarning;
            this.probeDeadlineMs = Math.max(100, Math.min(2000, probeDeadlineMs));
            this.failurePercent = Math.max(1, Math.min(100, failurePercent));
            this.failureWindow = Math.max(5, Math.min(100, failureWindow));
        }

        static Settings automatic()
        {
            return new Settings(1500, 3000, 3000, true, 400, 2, true, 600, 20, 10, true);
        }
    }

    /** Identifies a measurement's world and generation; creating a token sends no network request. */
    static final class ConnectionToken
    {
        final long generation;
        final int world;

        ConnectionToken(long generation, int world)
        {
            this.generation = generation;
            this.world = world;
        }
    }

    static final class Snapshot
    {
        final Mode mode;
        final Reason reason;
        final int world;
        final long tickAgeMs;
        final int pingMs;
        final boolean warmingUp;
        final Confidence confidence;
        int tcpRttMs = -1;
        String pingStatus = "";
        int normalPingMs = -1;
        int deadlineMs;

        Snapshot(Mode mode, Reason reason, int world, long tickAgeMs, int pingMs, boolean warmingUp)
        {
            this(mode, reason, world, tickAgeMs, pingMs, warmingUp,
                reason == Reason.NONE ? Confidence.NONE : Confidence.ALARM);
        }

        Snapshot(Mode mode, Reason reason, int world, long tickAgeMs, int pingMs, boolean warmingUp, Confidence confidence)
        {
            this.mode = mode;
            this.reason = reason;
            this.world = world;
            this.tickAgeMs = tickAgeMs;
            this.pingMs = pingMs;
            this.warmingUp = warmingUp;
            this.confidence = confidence;
        }

        boolean isAlarm()
        {
            return confidence == Confidence.ALARM;
        }
        boolean hasWarning()
        {
            return reason != Reason.NONE;
        }
    }

    private Settings settings = new Settings(1500, 3000, 3000, false, 400);
    private Mode mode = Mode.IDLE;
    private int world;
    private long generation;
    private long lastTick;
    private long suppressUntil;
    private long loadingUntil;
    private boolean haveTick;
    private long lastPing;
    private int pingMs = -1;
    private int highPings;
    private int healthyPings;
    private boolean pingAlarm;
    private boolean alarm;
    private int healthyTicks;
    private long testUntil;
    private boolean testing;
    private ConnectionToken pendingProbe;
    private long probeStarted;
    private int successes;
    private final boolean[] failedProbes = new boolean[100];
    private final long[] probeTimes = new long[100];
    private int sampleCount;
    private int sampleCursor;
    private int failures;
    private long lastProbeCompleted;
    private long lastClientTick;
    private boolean haveClientTick;
    private final LatencyBaseline baseline = new LatencyBaseline();
    private final TcpHealth tcp = new TcpHealth();
    private Object socketIdentity;

    synchronized void configure(Settings next)
    {
        if (settings.stallMs == next.stallMs && settings.loginGraceMs == next.loginGraceMs
            && settings.loadingGraceMs == next.loadingGraceMs && settings.pingEnabled == next.pingEnabled
            && settings.pingThresholdMs == next.pingThresholdMs && settings.highPingSamples == next.highPingSamples
            && settings.earlyWarning == next.earlyWarning && settings.probeDeadlineMs == next.probeDeadlineMs
            && settings.failurePercent == next.failurePercent && settings.failureWindow == next.failureWindow
            && settings.adaptive == next.adaptive)
        {
            return; // Sound/color changes must not reset network calibration.
        }
        settings = next;
        // Invalidate in-flight samples taken with the old settings.
        generation++;
        clearPing();
        resetProbes();
        tcp.reset();
    }

    synchronized void loggedIn(int currentWorld, long now)
    {
        if (mode == Mode.IDLE || world != currentWorld)
        {
            stop();
            world = currentWorld;
            mode = Mode.MONITORING;
            lastTick = now;
            suppressUntil = now + settings.loginGraceMs;
        }
        else if (mode == Mode.LOADING)
        {
            mode = Mode.MONITORING;
            // Permit one normal tick interval after loading, without an unbounded new grace.
            lastTick = now;
            haveTick = false;
        }
    }

    synchronized void loading(long now)
    {
        if (mode == Mode.MONITORING)
        {
            mode = Mode.LOADING;
            loadingUntil = now + settings.loadingGraceMs;
            generation++;
            clearPing();
            clearProbeHistory();
            baseline.pauseLearning();
            tcp.suspend();
        }
    }

    synchronized void connectionLost()
    {
        // This alarm is for early warning. A confirmed disconnect is already visible in the client.
        stop();
    }

    synchronized void stop()
    {
        generation++;
        mode = Mode.IDLE;
        world = 0;
        haveTick = false;
        haveClientTick = false;
        alarm = false;
        healthyTicks = 0;
        testing = false;
        clearPing();
        resetProbes();
        tcp.reset();
        socketIdentity = null;
    }

    synchronized void tick(long now)
    {
        if (mode == Mode.IDLE)
        {
            return;
        }
        long gap = now - lastTick;
        // Catch a long gap even if the watchdog itself was paused by a JVM stall.
        if (haveTick && mode == Mode.MONITORING && now >= suppressUntil && gap >= settings.stallMs)
        {
            alarm = true;
            healthyTicks = 0;
        }
        // Bursts of queued ticks are not evidence that live updates have stabilized.
        boolean normalInterval = haveTick && gap >= MIN_HEALTHY_TICK_INTERVAL_MS
            && gap < Math.min(MAX_HEALTHY_TICK_INTERVAL_MS, settings.stallMs);
        healthyTicks = normalInterval ? Math.min(2, healthyTicks + 1) : 0;
        haveTick = true;
        lastTick = now;
        mode = Mode.MONITORING;
    }

    synchronized void clientTick(long now)
    {
        if (mode != Mode.IDLE)
        {
            lastClientTick = now;
            haveClientTick = true;
        }
    }

    synchronized ConnectionToken trackSocketIdentity(Object identity)
    {
        if (mode != Mode.MONITORING)
        {
            return null;
        }
        if (socketIdentity != identity)
        {
            boolean replacing = socketIdentity != null;
            socketIdentity = identity;
            tcp.reset();
            if (replacing)
            {
                generation++;
                clearPing();
                resetProbes();
            }
        }
        return currentConnection();
    }

    synchronized void recordTcpSample(ConnectionToken connection, Object identity, int rtt,
        long transmitted, long retransmitted, long now)
    {
        if (!currentSocket(connection, identity))
        {
            return;
        }
        tcp.record(rtt, transmitted, retransmitted, gameUpdatesHealthy(now), now);
    }

    synchronized void markTcpUnavailable(ConnectionToken connection, Object identity)
    {
        if (currentSocket(connection, identity))
        {
            tcp.suspend();
        }
    }

    private boolean currentSocket(ConnectionToken connection, Object identity)
    {
        // State resets cannot cancel a native query already in progress. Discard its late result here.
        return mode == Mode.MONITORING && connection != null && connection.generation == generation
            && connection.world == world && identity != null && identity == socketIdentity;
    }

    private boolean gameUpdatesHealthy(long now)
    {
        return haveTick && now - lastTick < GAME_TICK_LATE_MS
            && (!haveClientTick || now - lastClientTick < CLIENT_TICK_STALE_MS);
    }

    synchronized ConnectionToken currentConnection()
    {
        return settings.pingEnabled && mode == Mode.MONITORING ? new ConnectionToken(generation, world) : null;
    }

    synchronized boolean beginIcmpProbe(ConnectionToken connection, long now)
    {
        if (connection == null || connection.generation != generation || mode != Mode.MONITORING || pendingProbe != null)
        {
            return false;
        }
        pendingProbe = connection;
        probeStarted = now;
        return true;
    }

    synchronized void recordIcmpSample(ConnectionToken connection, int result, long now)
    {
        if (connection == null || connection.generation != generation || connection.world != world
            || !settings.pingEnabled || mode != Mode.MONITORING)
        {
            return;
        }
        if (pendingProbe != null && pendingProbe != connection)
        {
            return;
        }
        pendingProbe = null;
        lastProbeCompleted = now;
        if (settings.adaptive)
        {
            boolean wasAvailable = baseline.isAvailable();
            baseline.record(result, gameUpdatesHealthy(now) && tcp.learningSafe(now), now);
            if (!wasAvailable && baseline.isAvailable())
            {
                // Do not carry old unavailable-period failures into a newly calibrated connection.
                sampleCount = sampleCursor = failures = 0;
            }
        }
        if (result >= 0)
        {
            successes = Math.min(3, successes + 1);
        }
        recordProbe(result < 0, now);
        // Old evidence must not combine with a sample that arrived much later.
        if (now - lastPing > ICMP_SAMPLE_MAX_AGE_MS)
        {
            clearPing();
        }
        lastPing = now;
        pingMs = result;
        if (result < 0)
        {
            clearPing(); // ICMP can be blocked; this is unknown, not proof of lag.
        }
        else if ((!settings.adaptive || baseline.isAvailable() || result >= 1000)
            && result >= (settings.adaptive ? baseline.highThreshold() : settings.pingThresholdMs))
        {
            healthyPings = 0;
            highPings = Math.min(settings.highPingSamples, highPings + 1);
            if (highPings >= settings.highPingSamples)
            {
                pingAlarm = true;
            }
        }
        else
        {
            highPings = 0;
            healthyPings = Math.min(2, healthyPings + 1);
            if (healthyPings >= 2)
            {
                pingAlarm = false;
            }
        }
    }

    synchronized void test(long now)
    {
        if (mode != Mode.IDLE)
        {
            testing = true;
            testUntil = now + TEST_ALERT_DURATION_MS;
        }
    }

    synchronized Snapshot evaluate(long now)
    {
        if (pingMs >= 0 && now - lastPing > ICMP_SAMPLE_MAX_AGE_MS)
        {
            clearPing();
        }
        long age = mode == Mode.IDLE ? 0 : Math.max(0, now - lastTick);
        boolean grace = mode != Mode.IDLE && now < suppressUntil;
        Reason reason = Reason.NONE;
        Confidence confidence = Confidence.NONE;
        if (mode != Mode.IDLE && !grace)
        {
            if (age >= settings.stallMs && (mode != Mode.LOADING || now >= loadingUntil))
            {
                reason = haveClientTick && now - lastClientTick >= CLIENT_TICK_STALE_MS
                    ? Reason.CLIENT_STALL : Reason.TICK_STALL;
            }
            else if (mode == Mode.MONITORING && settings.adaptive && tcp.repeatedRetries(now))
            {
                reason = Reason.TCP_RETRANSMISSIONS;
            }
            else if (mode == Mode.MONITORING && settings.adaptive && tcp.highLatency(now))
            {
                reason = Reason.TCP_LATENCY;
            }
            else if (mode == Mode.MONITORING && pingAlarm
                && (!settings.adaptive || baseline.isAvailable() || pingMs >= 1000))
            {
                reason = Reason.HIGH_PING;
            }
            else if (settings.pingEnabled && (settings.adaptive ? baseline.isAvailable() : successes >= 3))
            {
                int deadline = settings.adaptive ? baseline.deadline() : settings.probeDeadlineMs;
                if (settings.earlyWarning && pendingProbe != null && now - probeStarted >= deadline)
                {
                    reason = Reason.PROBE_DELAY;
                }
                else if (sampleCount == settings.failureWindow && now - lastProbeCompleted <= ICMP_COMPLETION_MAX_AGE_MS
                    && now - probeTimes[sampleCursor] <= ICMP_HISTORY_MAX_AGE_MS
                    && failures * 100 >= settings.failurePercent * sampleCount)
                {
                    reason = Reason.PROBE_FAILURES;
                }
            }
        }
        if (reason != Reason.NONE)
        {
            confidence = Confidence.ALARM;
            if (settings.adaptive)
            {
                boolean probeOnly = reason == Reason.PROBE_DELAY || reason == Reason.PROBE_FAILURES;
                boolean gameLate = haveTick && age >= GAME_TICK_LATE_MS;
                // ICMP alone is weaker evidence: require late game updates for failed/delayed probes,
                // and keep high ICMP latency silent while fresh TCP evidence and game updates are healthy.
                if ((probeOnly && !gameLate)
                    || (reason == Reason.HIGH_PING && tcp.healthy(now) && gameUpdatesHealthy(now)))
                {
                    confidence = Confidence.CAUTION;
                }
            }
        }
        if (confidence == Confidence.ALARM)
        {
            alarm = true;
            healthyTicks = 0;
        }
        else if (alarm)
        {
            if (healthyTicks >= 2)
            {
                alarm = false;
            }
            else
            {
                reason = Reason.RECOVERING;
                confidence = Confidence.ALARM;
            }
        }
        if (testing && now >= testUntil)
        {
            testing = false;
        }
        if (confidence != Confidence.ALARM && testing)
        {
            reason = Reason.TEST;
            confidence = Confidence.ALARM;
        }
        Snapshot snapshot = new Snapshot(mode, reason, world, age, pingMs, grace, confidence);
        snapshot.tcpRttMs = tcp.rtt();
        snapshot.pingStatus = settings.adaptive ? baseline.status() : "Fixed thresholds";
        snapshot.normalPingMs = settings.adaptive ? baseline.normalPing() : -1;
        snapshot.deadlineMs = settings.adaptive ? baseline.deadline() : settings.probeDeadlineMs;
        return snapshot;
    }

    synchronized int icmpProbeDelay()
    {
        return settings.adaptive ? baseline.retryDelay() : 500;
    }

    private void clearPing()
    {
        pingMs = -1;
        highPings = 0;
        healthyPings = 0;
        pingAlarm = false;
    }

    private void resetProbes()
    {
        baseline.reset();
        clearProbeHistory();
    }

    private void clearProbeHistory()
    {
        pendingProbe = null;
        successes = 0;
        sampleCount = 0;
        sampleCursor = 0;
        failures = 0;
    }

    private void recordProbe(boolean failed, long now)
    {
        if (sampleCount == settings.failureWindow)
        {
            if (failedProbes[sampleCursor])
            {
                failures--;
            }
        }
        else
        {
            sampleCount++;
        }
        failedProbes[sampleCursor] = failed;
        probeTimes[sampleCursor] = now;
        if (failed)
        {
            failures++;
        }
        sampleCursor = (sampleCursor + 1) % settings.failureWindow;
    }
}

package com.lagalarm;

import java.util.Arrays;

/** Robust per-world latency baseline and bounded retry policy. Called under the detector lock. */
final class LatencyBaseline
{
    private final int[] values = new int[61];
    private final int[] scratch = new int[61];
    private int count;
    private int cursor;
    private int consecutiveSuccesses;
    private int consecutiveFailures;
    private int median;
    private int deviation;
    private boolean available;
    private int burstRemaining;
    private long nextBurstAllowed;
    private int reference = -1;
    private int referenceDeviation;
    private long candidateSince = -1;
    private int candidatePing;
    private int candidateSamples;
    private long lastSample = -1;

    void reset()
    {
        count = cursor = consecutiveSuccesses = consecutiveFailures = median = deviation = 0;
        available = false;
        burstRemaining = 0;
        nextBurstAllowed = Long.MIN_VALUE;
        reference = -1;
        referenceDeviation = 0;
        pauseLearning();
        lastSample = -1;
    }

    void record(int rtt, boolean gameUpdatesHealthy, long now)
    {
        if (burstRemaining > 0)
        {
            burstRemaining--;
        }
        if (rtt < 0)
        {
            pauseLearning();
            consecutiveSuccesses = 0;
            burstRemaining = 0;
            consecutiveFailures = Math.min(8, consecutiveFailures + 1);
            if (consecutiveFailures >= 3)
            {
                // ICMP may have become blocked. Stop treating it as evidence about the game.
                available = false;
                count = cursor = 0;
                reference = -1;
            }
            return;
        }
        consecutiveFailures = 0;
        consecutiveSuccesses = Math.min(5, consecutiveSuccesses + 1);
        if (available && rtt >= highThreshold() && now >= nextBurstAllowed)
        {
            burstRemaining = 8;
            nextBurstAllowed = now + 30000;
        }
        if (!gameUpdatesHealthy || (lastSample >= 0 && now - lastSample > 2500))
        {
            pauseLearning();
        }
        lastSample = now;
        if (gameUpdatesHealthy)
        {
            values[cursor] = rtt;
            cursor = (cursor + 1) % values.length;
            count = Math.min(values.length, count + 1);
            System.arraycopy(values, 0, scratch, 0, count);
            Arrays.sort(scratch, 0, count);
            median = scratch[count / 2];
            for (int i = 0; i < count; i++)
            {
                scratch[i] = Math.abs(values[i] - median);
            }
            Arrays.sort(scratch, 0, count);
            deviation = scratch[count / 2];
        }
        if (!available && count >= 5 && consecutiveSuccesses >= 5)
        {
            available = true;
            reference = median;
            referenceDeviation = deviation;
        }
        else if (available && gameUpdatesHealthy)
        {
            // Keep a slow reference: gradual degradation must not raise its own alarm threshold.
            if (median < reference)
            {
                reference = median;
                referenceDeviation = deviation;
            }
            considerStableRoute(now);
        }
    }

    boolean isAvailable()
    {
        return available;
    }

    int normalPing()
    {
        return count == 0 ? -1 : reference < 0 ? median : reference;
    }

    int highThreshold()
    {
        // Require a large relative increase AND material absolute latency; always flag >= 1 second.
        int normal = Math.max(0, normalPing());
        int jitter = reference < 0 ? deviation : referenceDeviation;
        return Math.min(1000, Math.max(200, normal + Math.max(100, Math.max(normal, jitter * 6))));
    }

    int deadline()
    {
        return Math.min(2000, Math.max(400, Math.max(0, normalPing()) * 3
            + (reference < 0 ? deviation : referenceDeviation) * 6));
    }

    void pauseLearning()
    {
        candidateSince = -1;
        candidateSamples = 0;
    }

    private void considerStableRoute(long now)
    {
        if (count < 15)
        {
            return;
        }
        // A short window tests stability; its level must also stay near one fixed candidate
        // for two minutes. A moving window alone would quietly accept a slow upward ramp.
        for (int i = 0; i < 15; i++)
        {
            scratch[i] = values[(cursor - 1 - i + values.length) % values.length];
        }
        Arrays.sort(scratch, 0, 15);
        int recent = scratch[7];
        int tolerance = Math.max(20, recent / 10);
        if (recent > 500 || recent <= reference || scratch[14] - scratch[0] > tolerance)
        {
            pauseLearning();
            return;
        }
        if (candidateSince < 0 || Math.abs(recent - candidatePing) > Math.max(20, candidatePing / 10))
        {
            candidateSince = now;
            candidatePing = recent;
            candidateSamples = 0;
        }
        if (++candidateSamples >= 30 && now - candidateSince >= 120000)
        {
            reference = recent;
            referenceDeviation = deviation;
            pauseLearning();
        }
    }

    int retryDelay()
    {
        if (consecutiveFailures == 0)
        {
            return burstRemaining > 0 ? 250 : 1000;
        }
        return Math.min(30000, 1000 << Math.min(5, consecutiveFailures - 1));
    }

    String status()
    {
        if (available)
        {
            return "Active";
        }
        if (consecutiveFailures > 0)
        {
            return "Ping unavailable; retrying";
        }
        return "Learning ping " + Math.min(count, consecutiveSuccesses) + "/5";
    }
}

package com.lagalarm;

/** Passive socket evidence. Counters may count bytes or segments, so only like-unit ratios are used. */
final class TcpHealth
{
    private static final int EVIDENCE_MAX_AGE_MS = 2500;
    private static final int BASELINE_SAMPLE_INTERVAL_MS = 1000;
    private static final int HIGH_LATENCY_DURATION_MS = 500;
    private static final int RETRANSMISSION_WINDOW_MS = 3000;
    private static final double MIN_RETRANSMISSION_RATIO = 0.10;

    private final LatencyBaseline baseline = new LatencyBaseline();
    private final long[] times = new long[32];
    private final long[] sent = new long[32];
    private final long[] retried = new long[32];
    private int cursor;
    private int count;
    private long lastSent = -1;
    private long lastRetried;
    private long evidenceAt = -1;
    private long trainedAt = -1;
    private long highSince = -1;
    private int highSamples;
    private int healthySamples;
    private boolean high;
    private int rtt = -1;

    void reset()
    {
        baseline.reset();
        suspend();
    }

    void suspend()
    {
        lastSent = evidenceAt = trainedAt = highSince = -1;
        cursor = count = highSamples = healthySamples = 0;
        high = false;
        rtt = -1;
        baseline.pauseLearning();
    }

    void record(int latency, long transmitted, long retransmitted, boolean gameHealthy, long now)
    {
        if (latency <= 0 || transmitted < 0 || retransmitted < 0)
        {
            suspend();
            return;
        }
        if (lastSent < 0 || transmitted < lastSent || retransmitted < lastRetried)
        {
            // A socket replacement or counter wrap must never look like massive packet loss.
            if (lastSent >= 0)
            {
                reset();
            }
            lastSent = transmitted;
            lastRetried = retransmitted;
            return;
        }
        long deltaSent = transmitted - lastSent;
        long deltaRetry = retransmitted - lastRetried;
        lastSent = transmitted;
        lastRetried = retransmitted;
        if (deltaSent == 0 && deltaRetry == 0)
        {
            return;
        }
        // Identical snapshots are not fresh measurements and cannot keep a healthy verdict alive.
        if (evidenceAt >= 0 && now - evidenceAt > EVIDENCE_MAX_AGE_MS)
        {
            high = false;
            highSince = -1;
            highSamples = healthySamples = 0;
            baseline.pauseLearning();
        }
        evidenceAt = now;
        rtt = latency;
        times[cursor] = now;
        sent[cursor] = deltaSent;
        retried[cursor] = deltaRetry;
        cursor = (cursor + 1) % times.length;
        count = Math.min(times.length, count + 1);
        boolean clean = !hasRetries(now);
        if (!gameHealthy || !clean)
        {
            baseline.pauseLearning();
        }
        if (deltaSent > 0 && clean && (trainedAt < 0 || now - trainedAt >= BASELINE_SAMPLE_INTERVAL_MS))
        {
            baseline.record(latency, gameHealthy, now);
            trainedAt = now;
        }
        if ((baseline.isAvailable() || latency >= 1000) && latency >= baseline.highThreshold())
        {
            healthySamples = 0;
            if (highSince < 0)
            {
                highSince = now;
            }
            highSamples++;
            if (highSamples >= 2 && now - highSince >= HIGH_LATENCY_DURATION_MS)
            {
                high = true;
            }
        }
        else
        {
            highSince = -1;
            highSamples = 0;
            if (++healthySamples >= 2)
            {
                high = false;
            }
        }
    }

    boolean fresh(long now)
    {
        return evidenceAt >= 0 && now - evidenceAt <= EVIDENCE_MAX_AGE_MS;
    }

    boolean healthy(long now)
    {
        return fresh(now) && baseline.isAvailable() && rtt < baseline.highThreshold() && !hasRetries(now);
    }

    boolean learningSafe(long now)
    {
        return !fresh(now) || (!hasRetries(now) && (!baseline.isAvailable() || rtt < baseline.highThreshold()));
    }

    boolean highLatency(long now)
    {
        return fresh(now) && high;
    }

    int rtt()
    {
        return rtt;
    }

    int normalPing()
    {
        return baseline.normalPing();
    }

    boolean repeatedRetries(long now)
    {
        long totalSent = 0;
        long totalRetry = 0;
        int episodes = 0;
        for (int i = 0; i < count; i++)
        {
            if (now - times[i] > RETRANSMISSION_WINDOW_MS)
            {
                continue;
            }
            totalSent += sent[i];
            totalRetry += retried[i];
            if (retried[i] > 0)
            {
                episodes++;
            }
        }
        return fresh(now) && episodes >= 2 && totalRetry > 0
            && (totalSent == 0 || (double) totalRetry / totalSent >= MIN_RETRANSMISSION_RATIO);
    }

    private boolean hasRetries(long now)
    {
        for (int i = 0; i < count; i++)
        {
            if (now - times[i] <= RETRANSMISSION_WINDOW_MS && retried[i] > 0)
            {
                return true;
            }
        }
        return false;
    }
}

